let hitCount = 0

export const recordHit = (): number => {
  hitCount += 1
  return hitCount
}

const listeners = []

export const addListener = (listener) => {
  listeners.push(listener)
  return listeners
}

const flagState = { enabled: false }

export const enableFeature = () => {
  flagState.enabled = true
  return flagState.enabled
}

const sessions = new Map()

export const touchSession = (sessionId) => {
  const count = (sessions.get(sessionId) ?? 0) + 1
  sessions.set(sessionId, count)
  return count
}

let activeRegion = 'us-east'

export const setRegion = (region) => {
  activeRegion = region
}

export const currentRegion = () => activeRegion

let maintenanceMode = false

export const setMaintenanceMode = (value) => {
  maintenanceMode = value
}

export const isUnderMaintenance = () => {
  return maintenanceMode
}

const MAX_RETRIES = 3

export const clampRetries = (attempts) => {
  return attempts > MAX_RETRIES ? MAX_RETRIES : attempts
}

const STATUS_LABELS = Object.freeze({ open: 'Open', closed: 'Closed' })

export const labelFor = (status) => {
  return STATUS_LABELS[status] ?? 'Unknown'
}

const EMAIL_PATTERN = /^[^@\s]+@[^@\s]+\.[^@\s]+$/

export const isValidEmail = (value) => {
  return EMAIL_PATTERN.test(value)
}

const apiConfig = { baseUrl: 'https://api.example.test', timeoutMs: 5000 }

export const describeEndpoint = (path) => {
  return `${apiConfig.baseUrl}${path} (timeout ${apiConfig.timeoutMs}ms)`
}

const memo = new Map()

export const square = (value) => {
  if (memo.has(value)) return memo.get(value)
  const result = value * value
  memo.set(value, result)
  return result
}

const profileCache = new Map()

export const getProfile = (userId, load) => {
  if (profileCache.has(userId)) return profileCache.get(userId)
  const profile = load(userId)
  profileCache.set(userId, profile)
  return profile
}

let defaultLogger

const buildLogger = () => ({ log: (message) => message })

export const getDefaultLogger = () => {
  defaultLogger ??= buildLogger()
  return defaultLogger
}

let hitCount = 0

export const recordHit = () => {
  hitCount += 1
  return hitCount
}

let callCount = 0

export const greet = (name) => {
  return `hello ${name}`
}
